components.css:
*,*::before,*::after{box-sizing:border-box}
:root{color-scheme:light dark}
:root[data-theme="light"]{color-scheme:light}
:root[data-theme="dark"]{color-scheme:dark}
html{-webkit-text-size-adjust:100%;scroll-padding-top:5rem}
body{margin:0;background:var(--ds-background);color:var(--ds-text);font-family:var(--ds-font-body);font-size:var(--size-body);line-height:var(--line-body);font-variant-numeric:tabular-nums}
html[data-lang="cs"] body [lang="en"],html[data-lang="en"] body [lang="cs"]{display:none!important}
a{color:var(--color-accent-default);text-underline-offset:.18em;text-decoration-thickness:1px}
a:hover{text-decoration-thickness:2px}
code,kbd{font-family:var(--ds-font-mono);font-size:.875em;background:var(--color-bg-subtle);border:1px solid var(--ds-border);border-radius:var(--radius-sm);padding:.05em .3em;overflow-wrap:anywhere}
h1,h2,h3,h4{line-height:var(--line-tight);color:var(--ds-text);text-wrap:balance}
h3{font-size:var(--size-h3);font-weight:600;margin:var(--space-lg) 0 var(--space-sm)}
h4{font-size:var(--size-body);font-weight:600;margin:0 0 var(--space-xs)}
p,ul,ol,dl{margin:0 0 var(--space-sm)}
ul,ol{padding-left:1.25rem}
li+li{margin-top:.25rem}
strong{font-weight:600}
.pp-muted{color:var(--ds-muted)}
.pp-small{font-size:var(--size-small)}
.pp-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
:focus-visible{outline:2px solid var(--color-accent-default);outline-offset:2px}

.pp-topbar{position:sticky;top:0;z-index:20;background:var(--ds-background);border-bottom:1px solid var(--ds-border)}
.pp-topbar__inner{display:flex;align-items:center;gap:var(--space-sm);max-width:calc(var(--layout-toc) + var(--layout-wide) + var(--space-xl) + 2 * var(--space-md));margin:0 auto;padding:var(--space-xs) var(--space-md);min-height:3.25rem}
.pp-topbar__title{flex:1 1 auto;min-width:0;font-weight:600;font-size:var(--size-small);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pp-topbar__meta{display:flex;align-items:center;gap:var(--space-xs);flex-wrap:wrap}
.pp-lang{display:inline-flex;border:1px solid var(--color-border-strong);border-radius:999px;padding:2px;flex:none}
.pp-lang button{font:inherit;font-size:var(--size-small);font-weight:600;letter-spacing:.04em;border:0;border-radius:999px;padding:.25rem .7rem;background:transparent;color:var(--ds-muted);cursor:pointer}
.pp-lang button[aria-pressed="true"]{background:var(--ds-text);color:var(--ds-background)}
@media (max-width:640px){.pp-topbar__title{display:none}.pp-topbar__meta{flex:1 1 auto}}

.pp-layout{display:grid;grid-template-columns:var(--layout-toc) minmax(0,1fr);gap:var(--space-xl);max-width:calc(var(--layout-toc) + var(--layout-wide) + var(--space-xl) + 2 * var(--space-md));margin:0 auto;padding:var(--space-lg) var(--space-md) var(--space-xl)}
.pp-main{min-width:0;max-width:var(--layout-wide)}
.pp-main p,.pp-main ul,.pp-main ol,.pp-main dl,.pp-prose{max-width:var(--layout-measure)}
@media (max-width:960px){.pp-layout{grid-template-columns:minmax(0,1fr);gap:var(--space-md);padding-top:var(--space-md)}}

.pp-header{margin-bottom:var(--space-lg)}
.pp-kicker{font-size:var(--size-small);font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--ds-muted);margin:0 0 var(--space-xs)}
.pp-header h1{font-family:var(--ds-font-heading);font-size:var(--size-h1);font-weight:600;letter-spacing:-.015em;margin:0 0 var(--space-md)}
.pp-lead{font-size:var(--size-lead);line-height:1.55;max-width:var(--layout-measure);margin:0 0 var(--space-md)}
.pp-facts{display:flex;flex-wrap:wrap;gap:var(--space-xs) var(--space-md);margin:0;padding:var(--space-sm) 0 0;border-top:1px solid var(--ds-border);font-size:var(--size-small);color:var(--ds-muted)}
.pp-facts div{display:flex;gap:.35em}
.pp-facts dt{font-weight:600;color:var(--ds-text)}
.pp-facts dd{margin:0}
@media (max-width:640px){.pp-header h1{font-size:1.75rem}}
.pp-banner{border:1px dashed var(--color-border-strong);border-radius:var(--radius-md);padding:var(--space-xs) var(--space-sm);font-size:var(--size-small);color:var(--ds-muted);margin:0 0 var(--space-md);max-width:var(--layout-measure)}

.pp-toc{position:sticky;top:4.5rem;align-self:start;max-height:calc(100vh - 5.5rem);overflow:auto;font-size:var(--size-small)}
.pp-toc summary{font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--ds-muted);cursor:pointer;padding:var(--space-xs) 0;list-style:none}
.pp-toc summary::-webkit-details-marker{display:none}
.pp-toc ol{list-style:none;margin:0;padding:0;border-left:1px solid var(--ds-border)}
.pp-toc li{margin:0}
.pp-toc a{display:flex;gap:.6em;padding:.3rem .75rem;margin-left:-1px;border-left:2px solid transparent;color:var(--ds-muted);text-decoration:none;line-height:1.35}
.pp-toc a:hover{color:var(--ds-text)}
.pp-toc a[aria-current="true"]{color:var(--ds-text);border-left-color:var(--color-accent-default);font-weight:600}
.pp-toc__num{font-family:var(--ds-font-mono);font-size:.75rem;color:var(--color-text-faint);min-width:1.4em;padding-top:.1em}
@media (min-width:961px){.pp-toc summary{pointer-events:none}}
@media (max-width:960px){.pp-toc{position:static;max-height:none;border:1px solid var(--ds-border);border-radius:var(--radius-md);padding:0 var(--space-sm);background:var(--ds-surface)}.pp-toc summary{list-style:revert}.pp-toc ol{margin-bottom:var(--space-sm)}}

.pp-section{padding-top:var(--space-lg);margin-top:var(--space-lg);border-top:1px solid var(--ds-border)}
.pp-section>h2{display:flex;align-items:baseline;gap:.6em;font-family:var(--ds-font-heading);font-size:var(--size-h2);font-weight:600;letter-spacing:-.01em;margin:0 0 var(--space-md)}
.pp-section__num{font-family:var(--ds-font-mono);font-size:var(--size-small);font-weight:500;color:var(--color-text-faint)}
.pp-callout{border-left:3px solid var(--color-accent-default);background:var(--color-accent-soft);padding:var(--space-sm) var(--space-md);border-radius:0 var(--radius-md) var(--radius-md) 0;margin:0 0 var(--space-md);max-width:var(--layout-measure)}
.pp-callout p:last-child{margin-bottom:0}

.pp-table{overflow-x:auto;margin:0 0 var(--space-md);border:1px solid var(--ds-border);border-radius:var(--radius-md)}
.pp-table table{width:100%;border-collapse:collapse;font-size:var(--size-small);line-height:1.45}
.pp-table th,.pp-table td{text-align:left;vertical-align:top;padding:.55rem .75rem;border-bottom:1px solid var(--ds-border)}
.pp-table thead th{background:var(--ds-surface);font-weight:600;color:var(--ds-muted);white-space:nowrap}
.pp-table tbody tr:last-child>*{border-bottom:0}
.pp-table td.num,.pp-table th.num{text-align:right}
.pp-table .pp-col-agnes{background:var(--color-accent-soft)}
.pp-table thead .pp-col-agnes{color:var(--color-accent-default)}
.pp-table caption{caption-side:bottom;text-align:left;padding:.5rem .75rem;color:var(--ds-muted);font-size:var(--size-small)}
.pp-mark{display:inline-flex;align-items:center;gap:.4em;white-space:nowrap}
.pp-mark::before{content:"";flex:none;width:.7em;height:.7em;border-radius:50%;border:1.5px solid currentColor}
.pp-mark--yes{color:var(--ds-text)}
.pp-mark--yes::before{background:currentColor}
.pp-mark--partial{color:var(--ds-muted)}
.pp-mark--partial::before{background:linear-gradient(90deg,currentColor 50%,transparent 50%)}
.pp-mark--no{color:var(--color-text-faint)}
.pp-yn{display:inline-block;font-weight:600;font-size:.75rem;letter-spacing:.04em;text-transform:uppercase;padding:.1em .5em;border-radius:var(--radius-sm);border:1px solid var(--ds-border);color:var(--ds-muted);white-space:nowrap}
.pp-yn--yes{background:var(--color-accent-default);border-color:var(--color-accent-default);color:var(--color-accent-on)}

.pp-figure{margin:0 0 var(--space-md)}
.pp-figure figcaption{font-size:var(--size-small);color:var(--ds-muted);margin-top:var(--space-xs);max-width:var(--layout-measure)}
.pp-figure figcaption strong{color:var(--ds-text)}
.pp-shot__frame{position:relative;border:1px solid var(--ds-border);border-radius:var(--radius-md);overflow:hidden;background:var(--ds-surface)}
.pp-shot__frame img{display:block;width:100%;height:auto}
.pp-shot__overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.pp-shot__ring{fill:none;stroke:var(--color-accent-default);stroke-width:3;stroke-dasharray:8 6}
.pp-shot__pin circle{fill:var(--color-accent-default);stroke:var(--ds-background);stroke-width:3}
.pp-shot__pin text{fill:var(--color-accent-on);font-family:var(--ds-font-body);font-weight:700;font-size:20px;text-anchor:middle;dominant-baseline:central}
.pp-shot__notes{margin:var(--space-xs) 0 0;padding-left:1.5rem}
.pp-shot__notes li::marker{font-weight:700;color:var(--color-accent-default)}
.pp-shot--concept .pp-shot__frame{border:2px dashed var(--color-status-warn)}
.pp-shot--concept .pp-badge--concept{position:absolute;top:.6rem;left:.6rem;z-index:1}

.pp-decision{border:1px solid var(--ds-border);border-radius:var(--ds-radius);padding:var(--space-md);margin:0 0 var(--space-md);background:var(--ds-background)}
.pp-decision__head{display:flex;gap:var(--space-sm);align-items:baseline;margin-bottom:var(--space-sm)}
.pp-decision__id{font-family:var(--ds-font-mono);font-size:var(--size-small);font-weight:600;color:var(--color-accent-default);flex:none}
.pp-decision__head h3{margin:0;font-size:var(--size-h3)}
.pp-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(13rem,1fr));gap:var(--space-sm);margin:0 0 var(--space-sm)}
.pp-option{position:relative;border:1px solid var(--ds-border);border-radius:var(--radius-md);padding:var(--space-sm);background:var(--ds-surface)}
.pp-option p{font-size:var(--size-small);margin:0;color:var(--ds-muted)}
.pp-option__key{font-family:var(--ds-font-mono);font-weight:600;color:var(--ds-muted);margin-right:.3em}
.pp-option--recommended{border:2px solid var(--color-accent-default);background:var(--color-accent-soft)}
.pp-option__flag{display:inline-block;font-size:.75rem;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--color-accent-on);background:var(--color-accent-default);border-radius:var(--radius-sm);padding:.1em .45em;margin-bottom:.4rem}
.pp-reason{font-size:var(--size-small);margin:0 0 var(--space-sm);max-width:var(--layout-measure)}
.pp-form{border-top:1px solid var(--ds-border);padding-top:var(--space-sm)}
.pp-form fieldset{border:0;margin:0 0 var(--space-sm);padding:0}
.pp-form legend{font-weight:600;font-size:var(--size-small);margin-bottom:.35rem;padding:0}
.pp-form__choices{display:flex;flex-wrap:wrap;gap:.4rem}
.pp-form__choices label{display:inline-flex;align-items:center;gap:.4em;font-size:var(--size-small);border:1px solid var(--ds-border);border-radius:999px;padding:.3rem .75rem;cursor:pointer;background:var(--ds-surface)}
.pp-form__choices label:has(input:checked){border-color:var(--color-accent-default);background:var(--color-accent-soft);color:var(--ds-text)}
.pp-form__choices input{accent-color:var(--color-accent-default);margin:0}
.pp-form__comment{display:block;font-weight:600;font-size:var(--size-small);margin-bottom:var(--space-sm)}
.pp-form textarea{display:block;width:100%;max-width:var(--layout-measure);margin-top:.35rem;font:inherit;font-weight:400;font-size:var(--size-body);color:var(--ds-text);background:var(--ds-background);border:1px solid var(--color-border-strong);border-radius:var(--radius-md);padding:.5rem .65rem;resize:vertical}
.pp-button{font:inherit;font-size:var(--size-small);font-weight:600;border:1px solid var(--color-accent-default);background:var(--color-accent-default);color:var(--color-accent-on);border-radius:var(--radius-md);padding:.5rem 1rem;cursor:pointer}
.pp-button:hover{filter:brightness(1.08)}
.pp-form__note{font-size:var(--size-small);color:var(--ds-muted);margin:var(--space-xs) 0 0}
.pp-form__note[data-kind="error"]{color:var(--color-status-danger)}
.pp-form__off{font-size:var(--size-small);color:var(--ds-muted);border-top:1px solid var(--ds-border);padding-top:var(--space-sm);margin:0}
